using System;using System.Drawing;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;
namespace FIFA08Launcher {
public static class ModernAchievementCards {public static void Attach(Form form){var grid=form.Controls.OfType<DataGridView>().FirstOrDefault();if(grid==null)return;grid.Visible=false;var header=form.Controls.OfType<Panel>().FirstOrDefault(p=>p.Dock==DockStyle.Top);if(header!=null){header.Height=60;header.Padding=new Padding(14,8,14,8);foreach(var label in header.Controls.OfType<Label>())label.Font=new Font("Segoe UI",10.5f,FontStyle.Regular);}foreach(var panel in form.Controls.OfType<Panel>())foreach(var button in panel.Controls.OfType<Button>())if(!(button is RoundedButton))button.Visible=false;var list=new DarkFlowPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(10),BackColor=Color.FromArgb(18,18,21)};var host=new DarkScrollHost(list){Dock=DockStyle.Fill};form.Controls.Add(host);host.BringToFront();string last=null;Action refresh=()=>{string state=string.Join("|",grid.Rows.Cast<DataGridViewRow>().Select(r=>string.Join("/",r.Cells.Cast<DataGridViewCell>().Skip(1).Select(c=>Convert.ToString(c.Value)))));if(state==last)return;last=state;list.SuspendLayout();foreach(Control old in list.Controls.Cast<Control>().ToArray())old.Dispose();list.Controls.Clear();foreach(DataGridViewRow row in grid.Rows){var card=new Panel{Height=80,Width=Math.Max(240,list.ClientSize.Width-60),Margin=new Padding(0,0,0,7),BackColor=Color.FromArgb(26,26,30)};var icon=new PictureBox{Image=row.Cells[0].Value is Image?new Bitmap((Image)row.Cells[0].Value):null,SizeMode=PictureBoxSizeMode.Zoom,Location=new Point(12,20),Size=new Size(40,40)};icon.Disposed+=(s,e)=>{if(icon.Image!=null)icon.Image.Dispose();};card.Controls.Add(icon);card.Controls.Add(new Label{Text=Convert.ToString(row.Cells[2].Value),Font=new Font("Segoe UI",9.5f,FontStyle.Bold),ForeColor=Color.White,Location=new Point(64,5),Size=new Size(card.Width-78,20),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right});card.Controls.Add(new Label{Text=Convert.ToString(row.Cells[1].Value)+"  ·  "+Convert.ToString(row.Cells[3].Value)+" G",Font=new Font("Segoe UI",8.5f),ForeColor=(Convert.ToString(row.Cells[1].Value).StartsWith("Desbloqueado")||Convert.ToString(row.Cells[1].Value).StartsWith("Unlocked"))?Color.FromArgb(104,217,154):Color.FromArgb(170,170,180),Location=new Point(64,25),Size=new Size(card.Width-78,20),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right});card.Controls.Add(new Label{Text=Convert.ToString(row.Cells[4].Value),Font=new Font("Segoe UI",8.5f),ForeColor=Color.Silver,Location=new Point(64,44),Size=new Size(card.Width-78,33),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right});list.Controls.Add(card);}list.ResumeLayout();};EventHandler resize=(s,e)=>{list.SuspendLayout();foreach(Control card in list.Controls)card.Width=Math.Max(160,list.ClientSize.Width-60);list.ResumeLayout();list.PerformLayout();};list.Resize+=resize;list.VisibleChanged+=resize;var timer=new Timer{Interval=1000};timer.Tick+=(s,e)=>{if(list.Visible)refresh();};timer.Start();form.Disposed+=(s,e)=>timer.Dispose();refresh();}}
}
